<?php

namespace App\Support\Packages;

/**
 * What automatic recurring invoicing last did for a package agreement's
 * billing period (INV-1), as recorded on its enrollment.
 */
enum AutoInvoiceOutcome: string
{
    /** The period's invoice was generated by the cadence engine and issued. */
    case Issued = 'issued';

    /** The period's invoice would ask for nothing at all, so none was made. */
    case NothingToBill = 'nothing_to_bill';

    /** The period could not be invoiced; the refusal says why. An owner or admin sees it in Needs you. */
    case Refused = 'refused';

    /**
     * A period recorded as refused has since been invoiced another way - an
     * owner issued it by hand once the cause was fixed - so there is nothing
     * left to look at.
     */
    case Covered = 'covered';
}
